<?php
require_once __DIR__.'/../config/auth.php';require_role('owner');$pdo=db();$bid=branch_id();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['product_id'];$qty=(int)$_POST['quantity'];$type=$_POST['type'];if($qty>0&&in_array($type,['in','out'],true)){try{$pdo->beginTransaction();$p=$pdo->prepare('SELECT stock FROM products WHERE id=? AND branch_id=? FOR UPDATE');$p->execute([$id,$bid]);$current=$p->fetchColumn();if($current===false)throw new RuntimeException('Produk tidak ditemukan.');$delta=$type==='in'?$qty:-$qty;if((int)$current+$delta<0)throw new RuntimeException('Stok tidak mencukupi.');$pdo->prepare('UPDATE products SET stock=stock+? WHERE id=? AND branch_id=?')->execute([$delta,$id,$bid]);$pdo->prepare('INSERT INTO stock_movements(product_id,user_id,type,quantity,note) VALUES(?,?,?,?,?)')->execute([$id,user()['id'],$type,$delta,trim($_POST['note'])]);$pdo->commit();flash('success','Perubahan stok disimpan.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());}}redirect('/owner/stok.php');}
$s=$pdo->prepare('SELECT id,name,stock,min_stock FROM products WHERE branch_id=? AND is_active=1 ORDER BY name');$s->execute([$bid]);$products=$s->fetchAll();$s=$pdo->prepare('SELECT s.*,p.name product,u.name user_name FROM stock_movements s JOIN products p ON p.id=s.product_id JOIN users u ON u.id=s.user_id WHERE p.branch_id=? ORDER BY s.id DESC LIMIT 30');$s->execute([$bid]);$moves=$s->fetchAll();$pageTitle='Manajemen Stok';$active='stok';include __DIR__.'/../includes/header.php';?>
<div class="grid two-col"><section class="card"><h2>Catat stok</h2><form method="post" class="form-grid" style="margin-top:16px"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><label class="field full">Produk<select name="product_id" required><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?> — <?=$p['stock']?></option><?php endforeach;?></select></label><label>Jenis<select name="type"><option value="in">Stok masuk</option><option value="out">Stok keluar</option></select></label><label>Jumlah<input name="quantity" type="number" min="1" required></label><label class="field full">Catatan<input name="note" required></label><button class="btn primary">Simpan</button></form></section><section class="card"><h2>Posisi stok cabang</h2><table class="table"><tbody><?php foreach($products as $p):?><tr><td><?=e($p['name'])?></td><td class="<?=$p['stock']<=$p['min_stock']?'low-stock':''?>"><?=$p['stock']?></td></tr><?php endforeach;?></tbody></table></section></div><section class="card" style="margin-top:18px"><h2>Riwayat stok</h2><div class="table-wrap"><table class="table"><tbody><?php foreach($moves as $m):?><tr><td><?=date('d/m/Y H:i',strtotime($m['created_at']))?></td><td><?=e($m['product'])?></td><td><?=$m['quantity']>0?'+':''?><?=$m['quantity']?></td><td><?=e($m['note'])?></td><td><?=e($m['user_name'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php include __DIR__.'/../includes/footer.php';?>
